(function() {
    var export_bone, export_skin;

    Plugin.register('necromancer_exporter_4_4_1', {
        title: 'Necromancer Model Exporter for Veil 4.4.1',
        author: 'Elit_Terrator',
        icon: 'data:image/png;base64,', 
        description: 'Exports the model data for Veil\'s Necromancer',
		about: 'This plugin exports your Blockbench model as Java source files compatible with Veil\'s Necromancer system. It generates:\n\n- A Skeleton class with bone hierarchy and positions\n- A Skin class with cube geometry and UV mapping\n\nSupports box UV, per-face UV scaling, and bone rotation.\n\nFor more information see my GitHub page on the Details page.',
        version: '1.0.0',
        variant: 'both', 
		repository: 'https://github.com/ElitTerrator/Necromancer-Exporter-4.4.1',
        onload() {
			 
            // FIX: Changed "ExportAction" to the correct Blockbench class: "Action"
            export_bone = new Action('bone_file', {
                name: 'Export Skeleton',
                icon: 'pet_supplies',
                category: 'file',
                condition: () => !!Project, 
                click: function() {
					
					const modelName = (Project.name || 'Model')
						.trim()
						.replace(/(?:^|\s+)([a-zA-Z])/g, (match, letter) => letter.toUpperCase())
						.replace(/\s+/g, '');
					
					let outputText = ``;

					
					outputText += `public class ${modelName}Skeleton extends Skeleton {\n`;
					outputText += `    private static final Logger log = LoggerFactory.getLogger(${modelName}Skeleton.class);\n`;
					
					//add variables 
					outputText += `    protected Bone `;
					const boneNames = Group.all.map(group => `${group.name}	`);
					outputText += boneNames.join(', ');
					outputText += `;\n\n`;

					//Start class
                    outputText += `    public ${modelName}Skeleton() {\n`;
					outputText += `        super();\n`;
					
					Group.all.forEach(group => {
						let posX = group.origin[0];
						let posY = group.origin[1];
						let posZ = group.origin[2];

						if (group.parent instanceof Group) {
							posX -= group.parent.origin[0];
							posY -= group.parent.origin[1];
							posZ -= group.parent.origin[2];
						}


						let quatStr = 'new Quaternionf()';
						if (group.rotation[0] !== 0) quatStr += `.rotateX(${(group.rotation[0] * Math.PI) / 180}F)`;
						if (group.rotation[1] !== 0) quatStr += `.rotateY(${(group.rotation[1] * Math.PI) / 180}F)`;
						if (group.rotation[2] !== 0) quatStr += `.rotateZ(${(group.rotation[2] * Math.PI) / 180}F)`;

						outputText += `        Bone ${group.name}Bone = new Bone("${group.name}");\n`;
						outputText += `        ${group.name}Bone.setBaseAttributes(new Vector3f(${posX}F, ${posY}F, ${posZ}F), ${quatStr}, new Vector3f(), new Vector3f(1.0F), new Vector4f(1.0F));\n`;
						outputText += `        this.addBone(${group.name}Bone);\n`;
						outputText += `        this.${group.name} = ${group.name}Bone;\n\n`;
					});
					
					outputText += `\n`;
					Group.all.forEach(group => {
						if (group.parent instanceof Group) {
							outputText += `        ${group.parent.name}Bone.addChild(${group.name}Bone);\n`;
						}
					});
					outputText += `\n`;
					outputText += `        this.buildRoots();\n`;
					outputText += `    }\n`;
					outputText += `}`;
					

                    // 2. Trigger the file download
                    Blockbench.export({
                        type: 'Text File',
                        extensions: ['java'],
                        name: modelName + 'Skeleton',
                        content: outputText,
                        custom_writer: isApp ? null : (content, path) => {
                            var blob = new Blob([content], {type: "text/plain;charset=utf-8"});
                            saveAs(blob, path);
                        }
                    });
	
					
                }
            });

			export_skin = new Action('skin_file', {
                name: 'Export Skin',
                icon: 'circle',
                category: 'file',
                condition: () => !!Project,
                click: function() {
                    const modelName = (Project.name || 'Model')
                        .trim()
                        .replace(/(?:^|\s+)([a-zA-Z])/g, (match, letter) => letter.toUpperCase())
                        .replace(/\s+/g, '');


                    let outputText2 = `public class ${modelName}Skin {\n`;
					outputText2 += `    protected static final Skin SKIN;\n`;
					outputText2 += `\n`;
					
					outputText2 += `    static {\n`;
					outputText2 += `        Skin.Builder builder = Skin.builder(${Project.texture_width}, ${Project.texture_height});\n`;
					
					
					Group.all.forEach(group => {
						const cubesInGroup = Cube.all.filter(cube => cube.parent === group);
						if (cubesInGroup.length === 0) return; // skip groups with no direct cubes

						outputText2 += `        builder.startBone("${group.name}");\n`;

						function getFaceUVSize(cube, faceName) {
							const face = cube.faces[faceName];
							if (!face || !face.uv) return null;
							const [u1, v1, u2, v2] = face.uv;
							return [Math.abs(u2 - u1), Math.abs(v2 - v1)];
						}

						cubesInGroup.forEach(cube => {
							const posX = cube.from[0];
							const posY = cube.from[1];
							const posZ = cube.from[2];

							const sizeX = cube.to[0] - posX;
							const sizeY = cube.to[1] - posY;
							const sizeZ = cube.to[2] - posZ;

							let relX = posX - group.origin[0];
							let relY = posY - group.origin[1];
							let relZ = posZ - group.origin[2];

							const uvU = cube.uv_offset[0];
							const uvV = cube.uv_offset[1];

							// Pull the per-face UV rectangle sizes (in pixels) — north gives X/Y, east gives Z
							const [northW, northH] = getFaceUVSize(cube, 'north') || [sizeX, sizeY];
							const [eastW]          = getFaceUVSize(cube, 'east')  || [sizeZ, sizeY];

							const desiredX = northW;
							const desiredY = northH;
							const desiredZ = eastW;

							// inflate = half the difference between the actual box size and the UV-derived size
							const inflateX = (sizeX - desiredX) / 2;
							const inflateY = (sizeY - desiredY) / 2;
							const inflateZ = (sizeZ - desiredZ) / 2;
							
							relX += inflateX;
							relY += inflateY;
							relZ += inflateZ;

							outputText2 += `        builder.addCube(${desiredX}F, ${desiredY}F, ${desiredZ}F, ${relX}F, ${relY}F, ${relZ}F, ${inflateX}F, ${inflateY}F, ${inflateZ}F, ${uvU}F, ${uvV}F, false);\n\n`;
						});

						outputText2 += `\n`;
					});
					
					outputText2 += `        SKIN = builder.build();\n`;
					outputText2 += `    }\n\n`;                              // close static {}
					outputText2 += `    public static Skin getSKIN() { return SKIN; }\n`;
					outputText2 += `}`; 
					

                    Blockbench.export({
                        type: 'Text File',
                        extensions: ['java'],
                        name: modelName + 'Skin',
                        content: outputText2,
                        custom_writer: isApp ? null : (content, path) => {
                            var blob = new Blob([content], {type: "text/plain;charset=utf-8"});
                            saveAs(blob, path);
                        }
                    });
                }
            });

            MenuBar.addAction(export_bone, 'file.export');
            MenuBar.addAction(export_skin, 'file.export');
        },

        onunload() {
            // Clean up by removing the action when plugin is uninstalled
            export_bone.delete();
            export_skin.delete();
        }
    });
})();


